  /*
   * rep_add()
   *	parses the -s replacement string; compiles the regular expression
   *	and stores the compiled value and it's replacement string together in
   *	replacement string list. Input to this function is of the form:
   *		/old/new/pg
   *	The first char in the string specifies the delimiter used by this
   *	replacement string. "Old" is a regular expression in "ed" format which
   *	is compiled by regcomp() and is applied to filenames. "new" is the
   *	substitution string; p and g are options flags for printing and global
   *	replacement (over the single filename)
   * Return:
   *	0 if a proper replacement string and regular expression was added to
   *	the list of replacement patterns; -1 otherwise.
   */

  func rep_add(_ str : String) -> Result {
    char *pt1;
    char *pt2;
    REPLACE *rep;
    int res;
    char rebuf[BUFSIZ];

    // throw out the bad parameters
    if str.isEmpty {
      Tty.paxwarn(true, "Empty replacement string")
      return .failed
    }

    // first character in the string specifies what the delimiter is for this expression
    for (pt1 = str+1; *pt1; pt1++) {
      if (*pt1 == '\\') {
        pt1++;
        continue;
      }
      if (*pt1 == *str) {
        break;
      }
    }
    if (*pt1 == '\0') {

      Tty.paxwarn(true, "Invalid replacement string %s", str);
      return .failed;
    }

    /*
     * allocate space for the node that handles this replacement pattern
     * and split out the regular expression and try to compile it
     */
    if ((rep = (REPLACE *)malloc(sizeof(REPLACE))) == NULL) {
      Tty.paxwarn(true, "Unable to allocate memory for replacement string");
      return .failed;
    }

    *pt1 = '\0';
    if ((res = regcomp(&(rep->rcmp), str+1, 0)) != 0) {
      regerror(res, &(rep->rcmp), rebuf, sizeof(rebuf));
      Tty.paxwarn(true, "%s while compiling regular expression %s", rebuf, str);
      free(rep);
      return .failed;
    }

    /*
     * put the delimiter back in case we need an error message and
     * locate the delimiter at the end of the replacement string
     * we then point the node at the new substitution string
     */
    *pt1++ = *str;

    for (pt2 = pt1; *pt2; pt2++) {
      if (*pt2 == '\\') {
        pt2++;
        continue;
      }
      if (*pt2 == *str) {
        break;
      }
    }
    if (*pt2 == '\0') {

      regfree(&rep->rcmp);
      free(rep);
      Tty.paxwarn(true, "Invalid replacement string %s", str);
      return .failed;
    }

    *pt2 = '\0';
    rep->nstr = pt1;
    pt1 = pt2++;
    rep->flgs = 0;

    /*
     * set the options if any
     */
    while (*pt2 != '\0') {
      switch(*pt2) {
        case 'g':
        case 'G':
          rep->flgs  |= GLOB;
          break;
        case 'p':
        case 'P':
          rep->flgs  |= PRNT;
          break;
        default:
          regfree(&rep->rcmp);
          free(rep);
          *pt1 = *str;
          Tty.paxwarn(true, "Invalid replacement string option %s", str);
          return .failed;
      }
      ++pt2;
    }

    /*
     * all done, link it in at the end
     */
    rep->fow = NULL;
    if (rephead == NULL) {
      reptail = rephead = rep;
      return(0);
    }
    reptail->fow = rep;
    reptail = rep;
    return(0);
  }

  /*
   * pat_add()
   *	add a pattern match to the pattern match list. Pattern matches are used
   *	to select which archive members are extracted. (They appear as
   *	arguments to pax in the list and read modes). If no patterns are
   *	supplied to pax, all members in the archive will be selected (and the
   *	pattern match list is empty).
   * Return:
   *	0 if the pattern was added to the list, -1 otherwise
   */

  int
  pat_add(char *str, char *chdnam)
  {
    PATTERN *pt;

    /*
     * throw out the junk
     */
    if ((str == NULL) || (*str == '\0')) {
      Tty.paxwarn(true, "Empty pattern string");
      return .failed;
    }

    /*
     * allocate space for the pattern and store the pattern. the pattern is
     * part of argv so do not bother to copy it, just point at it. Add the
     * node to the end of the pattern list
     */
    if ((pt = (PATTERN *)malloc(sizeof(PATTERN))) == NULL) {
      Tty.paxwarn(true, "Unable to allocate memory for pattern string");
      return .failed;
    }

    pt->pstr = str;
    pt->pend = NULL;
    pt->plen = strlen(str);
    pt->fow = NULL;
    pt->flgs = 0;
    pt->chdname = chdnam;

    if (pathead == NULL) {
      pattail = pathead = pt;
      return(0);
    }
    pattail->fow = pt;
    pattail = pt;
    return(0);
  }

