  static char*
  extract_equiv_pat(char *pattern, char **pend)
  {
    int pat_len = 2;
    int found = 0;
    int is_double_bracket = 0;
    char* equiv_pat = NULL;

    if (*pattern == '\0' || pattern[1] == '\0' || pattern[2] == '\0')
        return NULL;

    /*
     * check if the pattern is
     * "[= =]", "[[= =][= =]]", "[: :]", or "[[: :][: :]]"
     * note that the full "pattern" string needs to be passed in
     */
    is_double_bracket = (*pattern == '[' && pattern[1] == '[');
    if (!(*pattern == '[') && !is_double_bracket) {
      return NULL;
    }

    pattern ++;

    if (is_double_bracket) {
      pattern ++;
      pat_len ++;
    }

    if (!(*pattern == ':') && !(*pattern == '=')) {
      return NULL;
    }

    pattern ++;


    for(; *pattern != '\0'; pat_len++, pattern++) {
      if (!is_double_bracket) {
        if ((*pattern == '=' || *pattern == ':')
            && pattern[1] == ']') {
          found = 1;
          pattern += 2;
          pat_len += 2;
          break;
        }

      } else {
        if ((*pattern == '=' || *pattern == ':')
            && pattern[1] == ']' && pattern[2] == ']') {
          found = 1;
          pattern += 3;
          pat_len += 3;
          break;
        }

      }
    }

    if (!found) {
      return NULL;
    }

    equiv_pat = strndup(pattern-pat_len, pat_len);

    if (equiv_pat == NULL) {
      Tty.paxwarn(true, "Out of memory");
      return NULL;
    }

    /*
     * set pend to the remaining pattern to be matched
     */
    if (pend != NULL) {
      *pend = pattern;
    }

    return equiv_pat;
  }

  static int
  regex_match(char *pattern, char *string, char **pend)
  {
    int res;
    regex_t preg;
    regmatch_t pmatch;
    char rebuf[BUFSIZ];

    if ((res = regcomp(&(preg), pattern, REG_EXTENDED)) != 0) {
      regerror(res, &(preg), rebuf, sizeof(rebuf));
      Tty.paxwarn(true, "%s while compiling pattern %s", rebuf, pattern);
      return .failed;
    }

    if (regexec(&(preg), string, 1, &(pmatch), 0) != 0) {
      regfree(&(preg));
      return .failed;
    }

    regfree(&(preg));

    /*
     * starting position of the match must be 0
     */
    if (pmatch.rm_so != 0) {
      return .failed;
    }

    /*
     * set pend to the remaining string to be matched
     */
    if (pend != NULL) {
      *pend = string + pmatch.rm_eo;
    }

    return(0);
  }

  static char *
  range_match(char *pattern, int test)
  {
    char c;
    char c2;
    int negate;
    int ok = 0;

    if ((negate = (*pattern == '!')) != 0)
        ++pattern;

    while ((c = *pattern++) != ']') {
      /*
       * Illegal pattern
       */
      if (c == '\0')
          return (NULL);

      if ((*pattern == '-') && ((c2 = pattern[1]) != '\0') &&
          (c2 != ']')) {
        if ((c <= test) && (test <= c2))
            ok = 1;
        pattern += 2;
      } else if (c == test)
                  ok = 1;
    }
    return (ok == negate ? NULL : pattern);
  }

